const $=s=>document.querySelector(s),hint=$('#hint'),toastEl=$('#toast');
function say(text){toastEl.textContent=text;toastEl.classList.add('show');toastTimer=2.7}
function setMission(title,copy,step){$('#missionTitle').textContent=title;$('#missionCopy').textContent=copy;document.querySelectorAll('.steps i').forEach((el,i)=>el.classList.toggle('on',i<=step))}
function dist2(a,b){return Math.hypot(a.x-b.x,a.z-b.z)}
function setHint(text){hint.textContent=text;hint.classList.toggle('show',!!text)}
function interact(){if(!started)return;if(inCar){if(Math.abs(speed)>2){say('Slow down before hopping out.');return}inCar=false;player.position.set(car.position.x+2,0,car.position.z);player.visible=true;say('Back on your feet.');return}if(dist2(player.position,car.position)<4){inCar=true;player.visible=false;say('The seat smells like old pine and petrol.');return}if(!hasParcel&&!done&&dist2(player.position,parcel.position)<4.2){hasParcel=true;parcel.visible=false;setMission('Parcel secured','Back to the red-roofed house. Take it easy on the bends.',1);say('Parcel in the passenger seat. Best not ask what is inside.');return}if(hasParcel&&dist2(player.position,home.position)<11){finish();return}if(dist2(player.position,parcel.position)<4.2&&!hasParcel){say('A parcel for the house. Pick it up.');return}}
function finish(){if(done)return;done=true;hasParcel=false;setMission('Home before supper','The parcel is delivered. Park by the porch and enjoy the last of the sun.',2);say('Errand done. The kettle can wait a minute.');$('#missionCopy').textContent='Errand complete. You made it home through the pines with the parcel intact. A fine Saturday.'}
function resetCar(){speed=0;car.position.set(0,0,15);car.rotation.y=Math.PI;fuel=Math.max(fuel,12);if(!inCar){player.position.set(-4,0,13)}say('The Satsuma is back in the yard.');}
function press(k){keys[k]=true;if(k==='e')interact();if(k==='r')resetCar()}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['w','a','s','d',' ','e','r','arrowup','arrowdown','arrowleft','arrowright'].includes(k)){e.preventDefault();if(!keys[k])press(k===' '? 'space':k)}});window.addEventListener('keyup',e=>{const k=e.key.toLowerCase();keys[k===' '?'space':k]=false});document.querySelectorAll('.touch').forEach(b=>{const k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);press(k)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>keys[k]=false)});
$('#startButton').addEventListener('click',()=>{started=true;$('#start').classList.add('hidden');say('Saturday, 14:26. The shop is waiting.');});
function forward(yaw){return new THREE.Vector3(Math.sin(yaw),0,Math.cos(yaw))}
function update(dt){if(!started)return;dt=Math.min(dt,.04);let moving=false;
 if(inCar){const throttle=keys.w||keys.arrowup,brake=keys.s||keys.arrowdown,turn=(keys.a||keys.arrowleft?1:0)-(keys.d||keys.arrowright?1:0);const hand=keys.space;
   if(throttle&&fuel>0){speed+= (speed<0?8:5.7)*dt;fuel-=dt*.055;engineOn=true}else if(brake){speed-= (speed>0?10:4)*dt}else{speed*=Math.exp(-.58*dt)}if(hand)speed*=Math.exp(-3.8*dt);speed=THREE.MathUtils.clamp(speed,-9,34);if(fuel<=0){fuel=0;speed*=Math.exp(-.7*dt)}
   const steerFactor=THREE.MathUtils.clamp(Math.abs(speed)/7,.12,1);car.rotation.y-=turn*steerFactor*dt*(speed<0?-1:1)*.92;const f=forward(car.rotation.y);car.position.x+=f.x*speed*dt;car.position.z+=f.z*speed*dt;
   // Soft shoulders and tree trunks give the road a little consequence.
   const nearest=curve.getUtoTmapping(0,0);let best=1e9;for(let i=0;i<=70;i++){const p=curve.getPoint(i/70);const d=(p.x-car.position.x)**2+(p.z-car.position.z)**2;if(d<best)best=d}const off=Math.sqrt(best);if(off>9.2){speed*=Math.exp(-1.3*dt);if(off>17){car.position.x-=f.x*speed*dt*1.3;car.position.z-=f.z*speed*dt*1.3}}
   car.position.x=THREE.MathUtils.clamp(car.position.x,-145,145);car.position.z=THREE.MathUtils.clamp(car.position.z,-205,65);shell.rotation.z=THREE.MathUtils.lerp(shell.rotation.z,-turn*Math.min(Math.abs(speed)/45,.08),dt*4);shell.rotation.x=THREE.MathUtils.lerp(shell.rotation.x,(throttle?-.025:brake?.025:0),dt*3);wheels.forEach(w=>w.rotation.x+=speed*dt*1.7);moving=Math.abs(speed)>.5;
 }else{const mx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),mz=(keys.w||keys.arrowup?1:0)-(keys.s||keys.arrowdown?1:0);if(mx||mz){const v=new THREE.Vector3(mx,0,-mz).normalize();player.position.addScaledVector(v,dt*4.2);player.rotation.y=Math.atan2(v.x,v.z);moving=true}player.position.x=THREE.MathUtils.clamp(player.position.x,-150,150);player.position.z=THREE.MathUtils.clamp(player.position.z,-205,65);legs.forEach((l,i)=>l.rotation.x=moving?Math.sin(performance.now()*.012+i*Math.PI)*.55:0)}
 const target=inCar?car.position:player.position;const yaw=inCar?car.rotation.y:player.rotation.y;const back=forward(yaw).multiplyScalar(inCar?10:6);const desired=new THREE.Vector3(target.x-back.x,target.y+(inCar?5.4:3.7),target.z-back.z);camera.position.lerp(desired,1-Math.exp(-dt*3.3));const look=new THREE.Vector3(target.x,target.y+(inCar?1.15:1.1),target.z);camera.lookAt(look);
